function validate([s]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 1000) return 's has between 2 and 1000 characters.';
  if (!/^[LR]+$/.test(s)) return "s contains only 'L' and 'R'.";
  let balance = 0;
  for (const ch of s) balance += ch === 'L' ? 1 : -1;
  if (balance !== 0) return "s must have as many 'L' as 'R' characters.";
  return null;
}

