function balancedStringSplit(s) {
  // best[i] is the most balanced pieces that exactly cover the first i characters (-1 when impossible).
  const n = s.length;
  const ells = [0];
  for (let i = 0; i < n; i++) ells.push(ells[i] + (s[i] === 'L' ? 1 : 0));
  const best = new Array(n + 1).fill(-1);
  best[0] = 0;
  for (let end = 1; end <= n; end++) {
    for (let start = 0; start < end; start++) {
      if (best[start] < 0) continue;
      const ls = ells[end] - ells[start];
      if (ls * 2 === end - start) best[end] = Math.max(best[end], best[start] + 1);
    }
  }
  return best[n];
}

