function generate(rand, size) {
  const large = size === 'large';
  const half = large ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 6);
  const shuffled = () => {
    const chars = [...'L'.repeat(half), ...'R'.repeat(half)];
    for (let i = chars.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [chars[i], chars[j]] = [chars[j], chars[i]];
    }
    return chars.join('');
  };
  // Either one random shuffle, or many short balanced chunks glued together (which gives many pieces).
  if (rand() < 0.5) return [shuffled()];
  let s = '';
  while (s.length < 2 * half) {
    const k = 1 + Math.floor(rand() * Math.min(3, half - s.length / 2));
    s += rand() < 0.5 ? 'L'.repeat(k) + 'R'.repeat(k) : 'R'.repeat(k) + 'L'.repeat(k);
  }
  return [s];
}
